/**
 * CLI JSON contract identity: the shape hash of the CLI schema bundle and the
 * generated files of `packages/rpc-contract` that carry the CLI contract
 * version. The hash follows the RPC contract rules (`./contract.ts`):
 * documentation (`description`, `title`, `$comment`, command `usage`) and
 * authoring order are excluded; every other change counts.
 */
import { CLI_CONTRACT_HISTORY, type CliContractBundle, type CliContractRelease } from "../../src/cli/contract";
import { schemaMap, sortedData } from "./contract";
import { parseDef } from "./model";
import { renderDef } from "./typescript";

/** Repository path of the CLI contract history, for messages and the base-branch lookup. */
export const CLI_CONTRACT_HISTORY_PATH = "packages/coding-agent/src/cli/contract/contract-history.json";

/** The release this build reports: the last entry of `CLI_CONTRACT_HISTORY`. */
export function currentCliContractRelease(): CliContractRelease {
	return CLI_CONTRACT_HISTORY[CLI_CONTRACT_HISTORY.length - 1];
}

/** The bundle reduced to its shape: documentation dropped, keys, sets, and commands sorted. */
export function cliContractShape(bundle: CliContractBundle): unknown {
	return {
		$schema: bundle.$schema,
		$id: bundle.$id,
		"x-cli": {
			commands: bundle["x-cli"].commands
				.toSorted((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
				.map(({ usage: _usage, ...command }) => sortedData(command)),
		},
		$defs: schemaMap(bundle.$defs),
	};
}

/** `sha256:<hex>` of the canonical JSON of `cliContractShape(bundle)`. */
export function cliContractSchemaHash(bundle: CliContractBundle): string {
	const hasher = new Bun.CryptoHasher("sha256");
	hasher.update(JSON.stringify(cliContractShape(bundle)));
	return `sha256:${hasher.digest("hex")}`;
}

/** Message for a bundle whose shape no longer matches the recorded release, or `null` when it does. */
export function cliContractDrift(bundle: CliContractBundle): string | null {
	const release = currentCliContractRelease();
	const schemaHash = cliContractSchemaHash(bundle);
	if (schemaHash === release.schemaHash) return null;
	return [
		`The CLI JSON shape changed but CLI contract ${release.version} records ${release.schemaHash}.`,
		`Append a new release to ${CLI_CONTRACT_HISTORY_PATH}`,
		`(semver: major for a breaking change, minor for an addition; see docs/rpc-contract.md):`,
		`\t{ "version": "<next>", "schemaHash": "${schemaHash}" }`,
		"then rerun `bun run gen:rpc`.",
	].join("\n");
}

/** `packages/rpc-contract/cli-contract.json`: the CLI version and shape hash for non-TypeScript consumers. */
export function emitCliContractJson(bundle: CliContractBundle): string {
	const contract = {
		cliContractVersion: currentCliContractRelease().version,
		schemaHash: cliContractSchemaHash(bundle),
		schema: "cli-contract.schema.json",
	};
	return `${JSON.stringify(contract, null, "\t")}\n`;
}

/** `packages/rpc-contract/src/cli.generated.ts`: the CLI version, shape hash, and output types. */
export function emitCliContractModule(bundle: CliContractBundle): string {
	const outputs = bundle["x-cli"].commands
		.map(command => `\t${JSON.stringify(command.name)}: ${command.output};\n`)
		.join("");
	return [
		"// Generated by `bun run gen:rpc` from packages/coding-agent/src/cli/contract. Do not edit.\n",
		"/** CLI JSON contract semver; independent of `RPC_CONTRACT_VERSION`. */",
		`export const CLI_CONTRACT_VERSION = ${JSON.stringify(currentCliContractRelease().version)};\n`,
		"/** `sha256:<hex>` shape hash of `cli-contract.schema.json` (documentation text and ordering excluded). */",
		`export const CLI_CONTRACT_SCHEMA_HASH = ${JSON.stringify(cliContractSchemaHash(bundle))};\n`,
		...Object.entries(bundle.$defs).map(([name, schema]) => renderDef(parseDef(name, schema))),
		`/** The stdout JSON of every contract command, by command name. */\nexport interface CliJsonOutputs {\n${outputs}}\n`,
	].join("\n");
}
